from autore import Modulo,estratto
from tikz_base import scrivi,n,a,rect,linea
m=Modulo('M11','Statistica spaziale','Coordinate, associazione e previsione nel territorio')
def p(t,s,**kw):m.pagina(t,s,**kw)
def d(i,b):return scrivi('M11',i,b)
m.sezione_nuova('Dato, posizione e supporto')
p('La disposizione spaziale delle osservazioni',
'''Un’indagine geologica associa a ciascuna misura una posizione e un supporto, che può essere un volume di carota, un affioramento o un’area campionata. Due insiemi aventi gli stessi valori possono descrivere configurazioni territoriali differenti, poiché la distribuzione marginale ignora la loro disposizione. Il capitolo utilizza sessantaquattro siti sintetici su un reticolo locale di passo 250 metri, nei quali la concentrazione è espressa in unità arbitrarie. La configurazione consente di esaminare separatamente rappresentazione cartografica, associazione e previsione.''',formula=r'\mathcal D=\{(s_i,z_i,A_i):i=1,\ldots,n\}',figura='M11/F01',didascalia='Reticolo sintetico 8 × 8; concentrazione in unità arbitrarie.',richiamo='Posizione, valore e supporto appartengono alla definizione dell’osservazione.',origine='M11:1–9')
p('Distribuzione marginale e configurazione geografica',
'''Permutando le concentrazioni fra i siti si conservano media, varianza, quantili e istogramma, mentre cambiano le relazioni fra misure vicine. Il confronto con la carta precedente mostra quanto la continuità visiva dipenda dall’abbinamento fra valori e posizioni. Tale operazione diventerà un riferimento inferenziale soltanto dopo avere specificato l’ipotesi di scambiabilità. Una semplice permutazione grafica serve già a distinguere le proprietà dell’insieme dei valori dalle proprietà della loro organizzazione nello spazio.''',formula=r'\{z_{\pi(i)}\}_{i=1}^n=\{z_i\}_{i=1}^n\quad\text{come multinsiemi}',figura='M11/F02',didascalia='Valori permutati sugli stessi siti; scala cromatica invariata.',richiamo='Una carta introduce informazione che un istogramma non conserva.',origine='M11:2,6,66–67')
p('Il supporto determina la quantità osservata',
'''Se una misura rappresenta la media entro un’area, il suo confronto con una misura puntuale richiede un modello del cambiamento di supporto. L’aggregazione attenua variazioni locali e modifica la covarianza, anche quando la grandezza fisica e l’unità rimangono identiche. Una carta di valori medi regionali non permette quindi di ricostruire le differenze interne a ciascuna regione. Nel reticolo didattico i siti vengono trattati come osservazioni puntuali ideali, rendendo esplicita una semplificazione che, nelle indagini reali, deve essere giustificata dal protocollo.''',formula=r'Z_A=\frac{1}{|A|}\int_A Z(s)\,\mathrm ds',tikz=d('D01',rect(.6,1,3.1,4.5)+rect(4.3,1,6.8,4.5,'Quantum')+r'\fill[Classical] (1.85,2.75) circle (3pt);'+n(1.85,5.2,'Misura puntuale',w=2.8,size=11)+n(5.55,2.75,r'$Z_A$',size=18)+n(5.55,5.2,'Media areale',w=2.8,size=11)+n(3.7,.35,'Due supporti di osservazione')),richiamo='L’unità statistica deve mantenere il medesimo significato lungo l’analisi.',origine='M11:4,7,43,82')
m.sezione_nuova('Coordinate e geometria')
p('Coordinate locali e riferimento geografico',
'''Le colonne x_m e y_m descrivono un piano locale con origine convenzionale, mentre lon e lat forniscono coordinate geografiche sintetiche prossime a 9° E e 45° N. La somiglianza delle estensioni non autorizza ad assegnare al piano locale un codice EPSG: il riferimento deve provenire dai metadati. Un controllo plausibile esamina identificativi, valori finiti, unità, ordine degli assi e collocazione attesa. Invertendo longitudine e latitudine si ottengono numeri globalmente ammissibili che collocano tuttavia i siti in un’altra regione.''',formula=r's_i=(x_i,y_i),\qquad [x_i]=[y_i]=\mathrm m',tikz=d('D02',rect(.5,1,3.3,3.1)+n(1.9,2.05,r'9° E\par45° N',w=2.4)+rect(4.1,1,6.9,3.1,'Quantum')+n(5.5,2.05,r'45° E\par9° N',w=2.4)+n(1.9,4,'Regione attesa',w=2.7,size=11)+n(5.5,4,'Assi invertiti',w=2.7,size=11)+n(3.7,5.4,'Entrambe le coppie superano i limiti globali.',w=6.8,size=11)),richiamo='La validità numerica delle coordinate deve essere accompagnata da una verifica geografica.',origine='M11:10–19')
c=estratto('M11','riferimento',"d <- read.csv('dati/spazio_v3.csv')\np <- sf::st_as_sf(d,coords=c('lon','lat'),\n crs='OGC:CRS84',remove=FALSE)\nq <- sf::st_transform(p,32632)\nb <- sf::st_coordinates(\n sf::st_transform(q,'OGC:CRS84'))\nstopifnot(max(abs(b-as.matrix(\n d[c('lon','lat')]))) < 1e-7)")
p('Assegnazione del CRS e trasformazione',
'''L’assegnazione del sistema di riferimento dichiara come interpretare numeri già presenti; la trasformazione calcola una nuova rappresentazione della medesima posizione. Il codice costruisce punti con ordine longitudine–latitudine esplicito e li trasforma in WGS 84 / UTM zona 32N. Il controllo di ritorno verifica la coerenza numerica dell’operazione entro una tolleranza prefissata. Tale controllo potrebbe riuscire anche partendo da un riferimento iniziale errato, poiché verifica la reversibilità della trasformazione scelta e non la correttezza dei metadati di partenza.''',codice=c,richiamo='Il controllo di ritorno integra la verifica dei metadati, dai quali dipende il significato della trasformazione.',fonti='sf: st_transform',origine='M11:20–23')
p('Distanze nel piano e sulla superficie terrestre',
'''Nel piano locale si impiega la distanza euclidea, la cui unità coincide con quella delle coordinate. Per coordinate angolari occorre invece scegliere una geometria sferica o ellissoidica, oppure una proiezione adeguata alla regione. La formula sferica usa angoli in radianti e un raggio terrestre dichiarato; un calcolo ellissoidico può restituire valori leggermente differenti. Nella matrice delle distanze, simmetria e diagonale nulla sono controlli necessari, mentre la loro soddisfazione non identifica la geometria più appropriata all’indagine.''',formula=r'd_{ij}=\sqrt{(x_i-x_j)^2+(y_i-y_j)^2}',destra='Nel reticolo, la diagonale fra i due angoli opposti vale 1750√2 m, circa 2475 m. La matrice D contiene 64 × 64 elementi; le distanze fra coppie distinte sono 2016 quando ogni coppia viene contata una sola volta.',richiamo='L’unità della distanza attraversa soglie, buffer, pesi e interpretazione dei risultati.',origine='M11:24–30')
m.sezione_nuova('Carte, appartenenze e aggregazioni')
p('Scala cromatica, geometria e copertura',
'''La carta di punti conserva il luogo nel quale la misura è stata acquisita, mentre una superficie continua richiede una regola di previsione fra i siti. Il rapporto unitario fra gli assi evita che una direzione venga deformata rispetto all’altra. Confronti fra carte richiedono la stessa scala cromatica e gli stessi limiti, affinché un colore mantenga il medesimo significato numerico. Anche i vuoti di campionamento devono rimanere riconoscibili, perché la densità dei simboli informa sulla copertura dell’indagine.''',figura='M11/F01',didascalia='Coordinate in metri, proporzioni uguali; misure nei soli siti.',richiamo='La grammatica cartografica deve conservare unità, geometria e copertura.',origine='M11:30–34')
p('Partizioni territoriali e appartenenze multiple',
'''La divisione Ovest–Est del laboratorio assegna all’Ovest i punti con x inferiore a 1000 metri e all’Est tutti gli altri, cosicché ogni identificativo compaia una sola volta. Due aree sovrapposte definiscono invece una relazione molti a molti: un punto può appartenere a entrambe. Con A definita da x minore o uguale a 1250 e B da x maggiore o uguale a 750, le sessantaquattro misure generano ottantotto relazioni. Una media calcolata sulla tabella delle relazioni attribuirebbe peso doppio ai ventiquattro punti comuni.''',formula=r'|A|+|B|=|A\cup B|+|A\cap B|=64+24=88',tikz=d('D03',rect(.5,1.2,4.7,3.9)+rect(2.7,1.2,6.9,3.9,'Quantum',12)+n(1.6,2.55,'A',size=18)+n(5.8,2.55,'B',size=18)+n(3.7,2.55,'24',size=18)+n(3.7,4.8,'64 punti · 88 relazioni',w=6.5)+n(3.7,5.6,'Le appartenenze non sono nuove misure.',w=6.7,size=11)),richiamo='Il denominatore dipende dall’unità della tabella: punti, aree o relazioni.',origine='M11:35–40,43–44')
p('Buffer e sensibilità alla scala di osservazione',
'''Un buffer seleziona i siti entro una distanza dichiarata da una posizione di interesse. Cambiando il raggio cambiano sia la numerosità sia la popolazione locale descritta dalla media. La scala dovrebbe derivare dal processo geologico, dalla risoluzione delle misure e dal quesito, evitando che venga scelta soltanto per ottenere un risultato favorevole. Nel caso sintetico si confrontano raggi di 300, 600 e 900 metri attorno al punto (750,750); la numerosità cresce, mentre la media può variare senza una direzione obbligata.''',formula=r'B_r(s_0)=\{s:\|s-s_0\|\le r\}\\ \overline z_r=\frac{\sum_i z_i\mathbf1\{s_i\in B_r(s_0)\}}{\sum_i\mathbf1\{s_i\in B_r(s_0)\}}',tikz=d('D04',r'\draw[Classical] (3.7,3) ellipse (1 and 1.14943);\draw[Quantum] (3.7,3) ellipse (1.7 and 1.95402);\draw[Measure] (3.7,3) ellipse (2.4 and 2.75862);\fill[Ink] (3.7,3) circle (2pt);'+a(3.7,3,6.1,3,'Measure')+n(5,2.5,'raggio r',size=11)+n(3.7,6,'La scala definisce il dominio della sintesi.',w=6.8,size=11)),richiamo='Una variazione del raggio modifica la domanda territoriale oltre alla precisione della stima.',origine='M11:41–44')
m.sezione_nuova('Vicinati e matrici dei pesi')
p('Costruzione del vicinato e pareggi geometrici',
'''Un vicinato può comprendere tutti i siti entro una soglia oppure un numero prefissato di siti prossimi. Nel reticolo regolare, più punti possono trovarsi alla stessa distanza minima: scegliere il primo nell’ordine della tabella introduce una convenzione che deve essere dichiarata. Per cercare il vicino più prossimo si esclude anzitutto il punto stesso, sostituendo la diagonale della matrice D con infinito. La soglia di 260 metri include invece tutti i vicini orizzontali e verticali, conservando i pareggi geometrici.''',formula=r'a_{ij}=\mathbf1\{0<d_{ij}\le260\}',figura='M11/F03',didascalia='I 112 segmenti rappresentano coppie non orientate; i siti hanno due, tre oppure quattro vicini.',richiamo='Soglia, metrica, pareggi e autoassociazioni sono parti della definizione del vicinato.',origine='M11:45–51')
c=estratto('M11','pesi',"d <- read.csv('dati/spazio_v3.csv')\nD <- as.matrix(dist(d[c('x_m','y_m')]))\nA <- 1*(D > 0 & D <= 260)\nnv <- rowSums(A)\nstopifnot(all(nv > 0))\nW <- A/nv\nstopifnot(max(abs(rowSums(W)-1)) < 1e-12)\nhead(data.frame(id=d$id,vicini=nv))")
p('Normalizzazione e assenza di vicini',
'''La matrice binaria A assegna peso unitario a ciascuna relazione ammessa. Dividendo ogni riga per il numero dei suoi vicini si ottiene W, le cui righe sommano a uno quando il sito possiede almeno un vicino. La trasformazione attribuisce peso totale uguale ai siti, pur producendo pesi individuali maggiori lungo il bordo. Un sito isolato genera un denominatore nullo e richiede una decisione esplicita: modificare il vicinato, escludere il sito con motivazione o adottare una convenzione coerente con l’analisi.''',formula=r'w_{ij}=\frac{a_{ij}}{\sum_k a_{ik}},\qquad \sum_jw_{ij}=1',codice=c,richiamo='La normalizzazione per riga può trasformare una matrice simmetrica in una matrice asimmetrica.',origine='M11:52–54,58–60')
p('Pesi di bordo e media del vicinato',
'''Un sito d’angolo divide il peso fra due vicini, assegnando a ciascuno un mezzo; un sito interno lo divide fra quattro vicini, assegnando un quarto. Perciò una relazione ammessa in entrambe le direzioni può avere pesi differenti nelle due righe di W. Il prodotto Wz restituisce la media locale dei valori contigui, purché l’ordine del vettore coincida con quello delle righe e delle colonne della matrice. Riordinare la sola tabella delle misure comprometterebbe tale corrispondenza senza necessariamente produrre un errore del software.''',formula=r'\widetilde z_i=\sum_jw_{ij}z_j',tikz=d('D05',n(1.2,1.5,'Angolo',w=2)+n(5.6,1.5,'Interno',w=2)+r'\fill[Classical] (1.2,3) circle (3pt);\fill[Quantum] (5.6,3) circle (3pt);'+a(1.2,3,2.7,3)+a(1.2,3,1.2,4.7)+a(5.6,3,4.2,3,'Quantum')+a(5.6,3,7,3,'Quantum')+a(5.6,3,5.6,1.9,'Quantum')+a(5.6,3,5.6,4.7,'Quantum')+n(2.1,2.45,'1/2',size=11)+n(6.4,2.45,'1/4',size=11)+n(3.7,5.6,'Somma dei pesi: uno per ciascun sito.',w=6.8,size=11)),richiamo='Gli identificativi devono accompagnare matrici, vettori e ogni riordinamento.',origine='M11:55–60')
m.sezione_nuova('Associazione spaziale e riferimento inferenziale')
p('L’indice di Moran come prodotto quadratico',
'''L’indice di Moran confronta il prodotto degli scarti nei siti collegati con la dispersione complessiva. Il fattore n diviso S₀ corregge la somma totale dei pesi, permettendo di riconoscere la convenzione utilizzata. Con pesi binari entro 260 metri, il reticolo produce un indice prossimo a 0,720. Sostituendo A con W cambia la ponderazione dei siti di bordo e può cambiare il valore dell’indice. La positività segnala concordanza rispetto al vicinato scelto, senza stabilire da sola quale processo l’abbia generata.''',formula=r'I=\frac{n}{S_0}\frac{\sum_i\sum_j a_{ij}(z_i-\overline z)(z_j-\overline z)}{\sum_i(z_i-\overline z)^2},\\ S_0=\sum_{ij}a_{ij}',destra='Il numeratore è un prodotto quadratico della matrice A con il vettore degli scarti centrati. Nel reticolo S₀ = 224, poiché ogni coppia non orientata compare due volte. Una matrice diversa definisce un confronto spaziale diverso.',richiamo='L’indice deve essere accompagnato dalla definizione dei pesi e dal dominio campionato.',origine='M11:61–65')
c=estratto('M11','moran',"d <- read.csv('dati/spazio_v3.csv')\nD <- as.matrix(dist(d[c('x_m','y_m')]))\nA <- 1*(D > 0 & D <= 260)\nv <- d$concentrazione-mean(d$concentrazione)\nI <- length(v)/sum(A)*\n sum(A*outer(v,v))/sum(v^2)\nI_m <- length(v)/sum(A)*\n as.numeric(t(v)%*%A%*%v)/sum(v^2)\nstopifnot(abs(I-I_m) < 1e-12)\nI")
p('Controllo numerico della formula di Moran',
'''Il codice costruisce esplicitamente gli scarti, i prodotti fra coppie e la somma dei pesi, rendendo verificabile ogni termine della formula. Una seconda implementazione mediante prodotto matriciale deve coincidere entro la tolleranza numerica. Questa equivalenza controlla il calcolo, mentre la pertinenza dei pesi rimane una scelta scientifica. Poiché una tendenza territoriale può generare concordanza fra siti vicini, l’indice calcolato sui valori grezzi combina eventuali gradienti sistematici e dipendenza residua.''',codice=c,richiamo='La correttezza dell’implementazione deve precedere l’interpretazione, che richiede ipotesi ulteriori.',origine='M11:63–65,70')
p('Diagramma degli scarti e media dei vicini',
'''Il diagramma mette in relazione lo scarto di ciascun sito con lo scarto medio del suo vicinato. I quadranti alto–alto e basso–basso raccolgono concordanze positive; gli altri due raccolgono discordanza locale. Con W normalizzata per riga e scarti centrati, la pendenza della regressione con intercetta coincide con la forma di Moran basata su W. Tale pendenza può differire dall’indice con pesi binari, poiché la normalizzazione cambia il contributo dei siti. Il diagramma descrive una relazione aggregata e non costituisce un test locale per ogni punto.''',formula=r'\widehat\beta=\frac{v^\top Wv}{v^\top v}=I_W',figura='M11/F04',didascalia='Ogni punto è un sito; l’ordinata usa i pesi normalizzati per riga. Le linee a zero delimitano i quattro quadranti.',richiamo='Grafico e indice devono impiegare la stessa convenzione dei pesi quando vengono confrontati.',origine='M11:57,61–65')
p('Permutazioni condizionate alle posizioni',
'''Il riferimento di permutazione mantiene fissi siti, pesi e insieme dei valori, riassegnando questi ultimi alle posizioni. La sua interpretazione richiede che, sotto l’ipotesi nulla, tali assegnazioni siano scambiabili. Nella revisione si utilizzano 999 permutazioni con seme documentato; il laboratorio originario ne conserva cento per rendere evidente la risoluzione limitata del calcolo. Il p-value unilaterale conta indici almeno pari a quello osservato, includendo la correzione di una unità che impedisce di attribuire probabilità nulla a un esito mai incontrato.''',formula=r'p_{\rm MC}=\frac{1+\sum_{b=1}^B\mathbf1\{I_b\ge I_{\rm obs}\}}{B+1}',figura='M11/F05',didascalia='Distribuzione ottenuta con 999 permutazioni; la linea viola individua l’indice osservato sui dati sintetici.',richiamo='Scambiabilità, direzione del confronto e numero di permutazioni definiscono il riferimento del test.',origine='M11:66–70')
p('Tendenza, residui e interpretazione geologica',
'''Una concentrazione che aumenta progressivamente verso Est può produrre un indice di Moran positivo anche quando gli scarti attorno al gradiente sono indipendenti. Se l’obiettivo riguarda l’associazione residua, occorre specificare prima il modello della media e valutare la dipendenza delle sue innovazioni o dei suoi residui. La stima del gradiente modifica la distribuzione del successivo indice, per cui permutare ingenuamente i residui richiede ulteriori giustificazioni. Il quesito geologico stabilisce se interessino il campo complessivo, il gradiente o la struttura rimasta dopo la sua rimozione.''',formula=r'Z(s)=m(s)+\varepsilon(s)',tikz=d('D06',rect(.5,.8,6.9,2)+n(3.7,1.4,'Campo osservato Z(s)',w=6)+a(2.2,2.2,2.2,3.2)+a(5.2,2.2,5.2,3.2,'Quantum')+rect(.5,3.4,3.5,4.8)+rect(3.9,3.4,6.9,4.8,'Quantum')+n(2,4.1,'Media m(s)',w=2.5)+n(5.4,4.1,r'Residuo $\varepsilon(s)$',w=2.6)+n(3.7,5.7,'L’associazione dipende dalla componente studiata.',w=6.9,size=11)),richiamo='Un indice di associazione spaziale non identifica automaticamente un meccanismo causale.',origine='M11:65,69,74')
m.sezione_nuova('Semivarianza e struttura a distanza')
p('Differenze quadratiche fra coppie di siti',
'''La semivarianza empirica raggruppa coppie di osservazioni secondo la loro distanza e calcola metà della differenza quadratica media. Nel caso sintetico il valore cresce alle distanze maggiori, coerentemente con la presenza di variazioni territoriali ampie. Ogni sito partecipa a molte coppie, cosicché le 2016 differenze non costituiscono altrettante repliche indipendenti. Classi di distanza, numerosità per classe, orientamento e presenza di tendenze devono accompagnare il grafico, del quale condizionano l’interpretazione.''',formula=r'\widehat\gamma(h)=\frac{1}{2|N(h)|}\sum_{(i,j)\in N(h)}[z_i-z_j]^2',figura='M11/F06',didascalia='Quattro classi di distanza; ogni coppia distinta entra una sola volta. Le numerosità sono esportate con i risultati R.',richiamo='Le coppie condividono osservazioni e non moltiplicano il numero di unità indipendenti.',origine='M11:71–74')
p('Covarianza e variogramma sotto stazionarietà',
'''Per un campo di secondo ordine stazionario, la covarianza dipende dallo spostamento fra due siti e la semivarianza è la differenza fra varianza marginale e covarianza. L’isotropia aggiunge l’ipotesi che conti soltanto la lunghezza dello spostamento, ignorandone la direzione. Un gradiente della media può violare la prima condizione; strutture geologiche orientate possono rendere inadeguata la seconda. Il variogramma descrittivo del reticolo viene pertanto presentato prima di qualunque adattamento di un modello stazionario.''',formula=r'\gamma(h)=\tfrac12\operatorname{Var}[Z(s+h)-Z(s)]\ =C(0)-C(h)',tikz=d('D07',n(3.7,.5,'Stessa distanza, direzioni differenti')+r'\fill[Ink] (3.7,3.7) circle (3pt);'+a(3.7,3.7,6.2,3.7)+a(3.7,3.7,3.7,.8264,'Quantum')+n(6.2,4.3,'Est–Ovest',size=11)+n(2,1.4,'Nord–Sud',size=11)+n(3.7,5,'L’isotropia attribuisce la stessa covarianza.',w=6.5,size=11)),richiamo='Stazionarietà e isotropia sono ipotesi del modello, da confrontare con la struttura geologica.',fonti='Spatial Data Science, cap. 12',origine='M11:71–74; approfondimento R5')
m.sezione_nuova('Copertura e unità della sintesi')
p('Campionamento di convenienza e copertura',
'''La selezione dei sedici siti lungo la strada fittizia, definita da y minore o uguale a 250 metri, conserva una buona copertura longitudinale e trascura gran parte della direzione Nord–Sud. Repliche precise entro questa fascia ridurrebbero l’incertezza locale senza ristabilire la rappresentatività dell’intero territorio. La carta del disegno permette di discutere quali ambienti siano assenti e quali ipotesi consentirebbero il trasferimento della sintesi. La differenza fra media della fascia e media del reticolo è un esito del caso sintetico, non una stima generale della distorsione di ogni campionamento stradale.''',figura='M11/F07',didascalia='Viola: sedici siti prossimi alla strada fittizia; grigio: quarantotto siti esclusi dalla selezione.',richiamo='La precisione entro il dominio osservato e la rappresentatività territoriale riguardano proprietà differenti.',origine='M11:75–77,83–84')
p('Medie di blocco e scelta dei pesi',
'''Suddividendo il reticolo in quattro blocchi da sedici siti, la media delle medie di blocco coincide con la media complessiva. Tale uguaglianza deriva dal bilanciamento e scompare quando le numerosità differiscono. Per due blocchi con medie 10 e 20 e numerosità 2 e 8, la media dei campioni vale 18, mentre la media equiponderata dei blocchi vale 15. La prima descrive i campioni, la seconda i blocchi equiponderati; una media areale richiederebbe pesi proporzionali alle superfici.''',formula=r'\overline z_{\rm campioni}=\frac{\sum_b n_b\overline z_b}{\sum_b n_b}\\ \overline z_{\rm blocchi}=\frac1K\sum_b\overline z_b',tikz=d('D08',rect(.5,1.2,2.3,3.8)+n(1.4,2.5,r'$n=2$\par$\overline z=10$',w=1.6,size=11)+rect(2.7,1.2,6.9,3.8,'Quantum')+n(4.8,2.5,r'$n=8$\par$\overline z=20$',w=3.8)+n(3.7,4.7,'Campioni: 18 · Blocchi: 15',w=6.6)+n(3.7,5.6,'Il peso esprime l’unità della domanda.',w=6.6,size=11)),richiamo='L’aggregazione deve conservare numerosità, superfici e definizione della popolazione di riferimento.',origine='M11:78–82')
m.sezione_nuova('Interpolazione e verifica geografica')
p('Interpolazione a distanza inversa',
'''L’interpolazione IDW stima il valore in una posizione priva di misura mediante una media pesata delle osservazioni. I pesi diminuiscono come una potenza della distanza e vengono normalizzati affinché sommino a uno. Aumentando l’esponente si concentra il contributo sui siti prossimi, mentre esponenti più piccoli distribuiscono l’informazione su un’area più ampia. La regola deve essere accompagnata da una scelta di metrica, vicinato e trattamento dei siti coincidenti. Il punto di esempio è situato a (900,900) metri, fra i nodi del reticolo.''',formula=r'\widehat z(s_0)=\sum_i\lambda_i(s_0)z_i,\qquad \lambda_i=\frac{d_{i0}^{-p}}{\sum_jd_{j0}^{-p}}',figura='M11/F10',didascalia='Pesi normalizzati per p = 1, 2 e 3. Le distanze si riferiscono alla medesima posizione da interpolare.',richiamo='La potenza controlla la località della media e deve essere valutata rispetto al compito predittivo.',origine='M11:85–89,91')
c=estratto('M11','idw',"d <- read.csv('dati/spazio_v3.csv')\nr <- sqrt((d$x_m-900)^2+(d$y_m-900)^2)\nstopifnot(all(r > 0))\nw <- r^-2; w <- w/sum(w)\nq <- sum(w*d$concentrazione)\nstopifnot(abs(sum(w)-1) < 1e-12,\n q >= min(d$concentrazione),\n q <= max(d$concentrazione))\nq")
p('Vincoli della media pesata e siti coincidenti',
'''La positività dei pesi normalizzati mantiene ogni previsione IDW entro l’intervallo dei valori utilizzati. Questa proprietà offre un controllo numerico e delimita la capacità del metodo di rappresentare estremi non osservati. Se la posizione richiesta coincide con un sito campionato, la distanza nulla deve essere trattata prima dell’elevamento a potenza negativa. Con una sola misura si restituisce il valore del sito; con repliche discordanti occorre definire un modello o una regola di aggregazione, poiché l’interpolazione esatta di entrambe sarebbe impossibile.''',formula=r'\min_i z_i\le\widehat z(s_0)\le\max_i z_i',codice=c,richiamo='La gestione delle coincidenze appartiene al modello dei dati e deve precedere il calcolo dei pesi.',origine='M11:89–91')
p('Superficie interpolata e provenienza dei dati',
'''Applicando IDW con potenza due a un reticolo più fitto si ottiene una superficie continua di valori previsti, sulla quale vengono sovrapposti i siti originari. La maggiore densità delle celle migliora la rappresentazione grafica della regola e lascia invariata l’informazione osservativa. Nei settori poco coperti, una superficie visivamente regolare può nascondere l’ampia distanza dalle misure. La carta deve quindi indicare metodo, parametri, unità, copertura e data dell’analisi, affinché il lettore possa distinguere il dato acquisito dalla previsione.''',figura='M11/F08',didascalia='IDW di potenza due; siti misurati e griglia di 45 × 45 celle.',richiamo='La risoluzione grafica di una superficie non coincide con la risoluzione informativa del campionamento.',origine='M11:92,100,104')
p('Kriging ordinario: vincolo e modello di covarianza',
'''Il kriging ordinario cerca una previsione lineare a varianza d’errore minima, imponendo la non distorsione rispetto a una media ignota costante. I pesi derivano dal modello di covarianza e dalla geometria del campionamento; possono assumere valori negativi. Il sistema affianca alla matrice C delle covarianze il vincolo di somma unitaria, mentre c₀ raccoglie le covarianze fra siti osservati e posizione richiesta. La varianza di kriging è condizionata al modello specificato e richiede attenzione all’incertezza dei suoi parametri.''',formula=r'\begin{pmatrix}C&\mathbf1\\\mathbf1^\top&0\end{pmatrix}\begin{pmatrix}\lambda\\\nu\end{pmatrix}=\begin{pmatrix}c_0\\1\end{pmatrix}',destra='Questa estensione formalizza il passaggio da una regola geometrica a un modello stocastico. Il reticolo con gradiente richiederebbe prima un modello della media, che potrebbe condurre al kriging universale. Il laboratorio principale conserva IDW per rendere espliciti i pesi senza occultare tali scelte.',richiamo='La previsione geostatistica dipende dalla plausibilità del modello della media e della covarianza.',fonti='Spatial Data Science, cap. 12',origine='M11:108; approfondimento R5')
p('Separazione geografica di addestramento e test',
'''La verifica lascia fuori i ventiquattro siti con x maggiore o uguale a 1250 metri, utilizzando i quaranta siti occidentali per costruire le previsioni. Il settore di test si trova oltre l’estensione dell’addestramento lungo x, per cui l’esperimento valuta un trasferimento geografico più impegnativo dell’interpolazione fra punti circondati da misure. Una suddivisione casuale mescolerebbe invece siti prossimi, fornendo una valutazione pertinente a un’altra disponibilità di informazione. La geometria del test deve riprodurre l’impiego previsto del metodo.''',formula=r'\mathcal T=\{i:x_i<1250\},\qquad\mathcal V=\{i:x_i\ge1250\}',tikz=d('D09',rect(.5,1,4.5,4.6)+rect(4.7,1,6.9,4.6,'Quantum')+n(2.5,2.5,r'40 siti\par addestramento',w=3.5)+n(5.8,2.5,r'24 siti\par test',w=1.9,size=11)+a(4.1,3.9,5.6,3.9,'Quantum')+n(3.7,5.5,'Il test estende il dominio verso Est.',w=6.7,size=11)),richiamo='La separazione geografica va progettata insieme alla domanda di trasferibilità.',origine='M11:93–95,98–99')
p('Grandezza, segno e distribuzione degli errori',
'''Gli errori, definiti come osservato meno previsto, distinguono sottostime e sovrastime. MAE e RMSE riassumono la loro grandezza, mentre la media degli errori descrive la direzione prevalente. La carta permette di individuare una struttura geografica che tali sintesi potrebbero nascondere. Il risultato riguarda il settore Est e la potenza IDW prefissata; modifiche suggerite dal test richiederebbero una nuova verifica indipendente.''',formula=r'e_i=z_i-\widehat z_i,\quad\operatorname{MAE}=\frac1m\sum_i|e_i|\\\operatorname{RMSE}=\sqrt{\frac1m\sum_ie_i^2}',figura='M11/F09',didascalia='Siti di stima in grigio; colore degli errori nel settore Est. La linea tratteggiata separa i due domini.',richiamo='La carta degli errori integra le metriche aggregate e rende visibile il dominio della verifica.',origine='M11:96–99')
m.sezione_nuova('Consegna e studio autonomo')
c=estratto('M11','geojson',"d <- read.csv('dati/spazio_v3.csv')\np <- sf::st_as_sf(d,coords=c('lon','lat'),\n crs='OGC:CRS84')\nf <- tempfile(fileext='.geojson')\nsf::st_write(p,f,quiet=TRUE)\nq <- sf::st_read(f,quiet=TRUE)\nstopifnot(nrow(q)==nrow(p),\n setequal(q$id,p$id),\n isTRUE(all.equal(q$concentrazione,\n p$concentrazione)))\nunlink(f)")
p('Esportazione e controllo del contenuto geografico',
'''La consegna comprende dati, sistema di riferimento, identificativi, codice e parametri, insieme alle carte delle osservazioni, delle previsioni e degli errori. Il GeoJSON viene riletto per verificare che geometrie e attributi utili siano stati conservati. La corrispondenza deve essere controllata per identificativo quando l’ordine delle righe può cambiare; nel frammento l’ordine resta quello della scrittura. Registrare le versioni di R, sf, GDAL e PROJ permette inoltre di ricostruire il contesto delle operazioni geometriche.''',codice=c,richiamo='Una consegna geografica è verificabile quando preserva dati, riferimento e procedimento di analisi.',origine='M11:101–104')
p('Percorso di laboratorio e problema di trasferimento',
'''I laboratori N01–N07 affrontano coordinate, distanze e rappresentazione; N08–N12 definiscono appartenenze, buffer e pesi; N13–N15 trattano Moran, permutazioni e semivarianza; N16–N20 completano copertura, aggregazione, interpolazione, verifica ed esportazione. Per lo studio autonomo si consideri una concentrazione misurata soltanto presso una strada, che debba essere prevista su un versante remoto. L’argomentazione deve precisare popolazione, supporto, accessibilità, differenze ambientali e geometria della validazione, prima di scegliere un interpolatore.''',tikz=d('D10',rect(.5,.6,6.9,1.8)+n(3.7,1.2,'Dati, supporto e disegno',w=6)+a(3.7,2,3.7,2.5)+rect(.5,2.7,6.9,3.9,'Quantum')+n(3.7,3.3,'Modello e dominio della previsione',w=6,size=11.5)+a(3.7,4.1,3.7,4.6)+rect(.5,4.8,6.9,6)+n(3.7,5.4,'Verifica geografica e consegna',w=6,size=11.5)),richiamo='Il trasferimento a un territorio diverso richiede ipotesi sulle differenze fra dominio osservato e dominio previsto.',origine='M11:105–110')
m.inserisci_dopo('Distanze nel piano e sulla superficie terrestre',titolo='Distanza sferica e unità angolari',testo='La distanza lungo un arco di cerchio massimo si ricava da latitudini e longitudini espresse in radianti. Nella formula, a raccoglie la separazione angolare e R rappresenta il raggio della sfera adottata. Il laboratorio usa il modello sferico come confronto esplicito con la geometria piana; la precisione di un calcolo territoriale reale dipende anche dal datum, dall’estensione e dalla scelta fra sfera ed ellissoide. Le convenzioni geometriche devono accompagnare il risultato.',formula=r'a=\sin^2\frac{\Delta\varphi}{2}+\cos\varphi_i\cos\varphi_j\sin^2\frac{\Delta\lambda}{2}\\ d=2R\arcsin\sqrt a',destra='La conversione da gradi a radianti moltiplica per π/180. Inserire direttamente i gradi nelle funzioni trigonometriche di R produrrebbe un risultato numerico privo della geometria desiderata. Il raggio R determina l’unità della distanza finale.',richiamo='La conversione angolare è parte del procedimento di calcolo e deve essere verificata.',origine='M11:27–29')
m.salva()
